
from agent_security.events import AgentEvent


class EventMonitor:
    """Collects and tracks events generated by AI agents."""

    def __init__(self):
        self.events = []

    def collect_event(self, event: AgentEvent):
        """Collect one agent event."""

        self.events.append(event)

    def collect_events(self, events: list[AgentEvent]):
        """Collect multiple agent events."""

        self.events.extend(events)

    def get_events(self):
        """Return all collected events."""

        return self.events.copy()

    def get_summary(self):
        """Return basic statistics about collected events."""

        total = len(self.events)

        successful = sum(
            event.status == "success" for event in self.events
        )

        failed = sum(
            event.status == "failure" for event in self.events
        )

        blocked = sum(
            event.status == "blocked" for event in self.events
        )

        return {
            "total_events": total,
            "successful_events": successful,
            "failed_events": failed,
            "blocked_events": blocked
        }
